import React, { useEffect, useState } from "react";
import {
  LineChart,
  ResponsiveContainer,
  Legend,
  Tooltip,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
} from "recharts";
import { getAccessToken } from "../../helpers/authUtils";
import useWebSocket, { ReadyState } from "react-use-websocket";
import { Card } from "antd";
import { useStateContext } from "../../contexts/ContextProvider";

function Dashboard() {
  const [userToken, setUserToken] = useState();
  const [retailerDashboardData, setretailerDashboardData] = useState();
  const { currentColor } = useStateContext();

  useEffect(() => {
    setUserToken(getAccessToken());
  }, []);

  const { readyState, sendJsonMessage } = useWebSocket(
    userToken ? `wss://api.wazipos.com/ws/retailers/dashboard/` : null,
    {
      queryParams: {
        token: userToken ? userToken : "",
      },

      onOpen: () => {
        console.log("Connected!");
      },
      onClose: () => {
        console.log("Disconnected!");
      },

      // New onMessage handler
      onMessage: (e) => {
        const data = JSON.parse(e.data);
        console.log("data..", data);
        setretailerDashboardData(data.retailer_dashboard);
      },
    }
  );

  const connectionStatus = {
    [ReadyState.CONNECTING]: "Connecting",
    [ReadyState.OPEN]: "Open",
    [ReadyState.CLOSING]: "Closing",
    [ReadyState.CLOSED]: "Closed",
    [ReadyState.UNINSTANTIATED]: "Uninstantiated",
  }[readyState];

  let tabs = [
    {
      id: "photos",
      label: "Photos",
      content:
        "Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat.",
    },
    {
      id: "music",
      label: "Music",
      content:
        "Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur.",
    },
    {
      id: "videos",
      label: "Videos",
      content:
        "Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.",
    },
  ];

  const quickLinks = () => {
    return (
      <div className="flex w-full flex-col border border-gray-200 my-2 mx-1">
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-5 m-2">
          <Card
            className="flex items-center justify-center flex-col"
            title="Followers"
            bordered={true}
          >
            {retailerDashboardData && retailerDashboardData.followers ? (
              <h1
                className="font-bold"
                style={{ color: currentColor, fontSize: 24 }}
              >
                {retailerDashboardData.followers}
              </h1>
            ) : (
              <h1
                className="font-bold"
                style={{ color: currentColor, fontSize: 24 }}
              >
                ---
              </h1>
            )}
          </Card>

          <Card
            className="flex items-center justify-center flex-col"
            title="Inventory items"
            bordered={true}
          >
            {retailerDashboardData && retailerDashboardData.followers ? (
              <h1
                className="font-bold"
                style={{ color: currentColor, fontSize: 24 }}
              >
                {retailerDashboardData.retailer_receipts}
              </h1>
            ) : (
              <h1
                className="font-bold"
                style={{ color: currentColor, fontSize: 24 }}
              >
                ---
              </h1>
            )}
          </Card>
          <Card
            className="flex items-center justify-center flex-col"
            title="Customer Orders"
            bordered={true}
          >
            {retailerDashboardData && retailerDashboardData.followers ? (
              <h1
                className="font-bold"
                style={{ color: currentColor, fontSize: 24 }}
              >
                {retailerDashboardData.customer_orders}
              </h1>
            ) : (
              <h1
                className="font-bold"
                style={{ color: currentColor, fontSize: 24 }}
              >
                ---
              </h1>
            )}
          </Card>

          <Card
            className="flex items-center justify-center flex-col"
            title="Wholesale Requisitions"
            bordered={true}
          >
            {retailerDashboardData && retailerDashboardData.followers ? (
              <h1
                className="font-bold"
                style={{ color: currentColor, fontSize: 24 }}
              >
                {retailerDashboardData.wholesale_requisitions}
              </h1>
            ) : (
              <h1
                className="font-bold"
                style={{ color: currentColor, fontSize: 24 }}
              >
                ---
              </h1>
            )}
          </Card>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 mt-5 m-2">
          {retailerDashboardData && retailerDashboardData.weekly_orders ? (
            <div className="bg-white rounded-sm p-5">
              <div className="flex flex-col items-center justify-center">
                <h1 className="text-heading font-bold text-2xl">
                  This Week Sales
                </h1>
                <ResponsiveContainer width="100%" aspect={3}>
                  <LineChart
                    data={retailerDashboardData.weekly_orders}
                    margin={{ right: 10 }}
                  >
                    <CartesianGrid />
                    <XAxis dataKey="date" interval={"preserveStartEnd"} />
                    <YAxis></YAxis>
                    <Legend />
                    <Tooltip />
                    <Line dataKey="items" stroke="black" activeDot={{ r: 8 }} />
                    <Line
                      dataKey="orders"
                      stroke="green"
                      activeDot={{ r: 8 }}
                    />
                    <Line dataKey="value" stroke="red" activeDot={{ r: 8 }} />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            </div>
          ) : (
            <div></div>
          )}
          <div></div>
        </div>

        {/**<Tabs
          fullWidth
          radius="none"
          size="lg"
          aria-label="Form tabs"
          items={tabs}
        >
          <Tab id="/" href="/retailers/orders" title="Orders" />
          <Tab
            id="/inventory"
            href="/retailers/inventory"
            title={
              <div className="flex flex-row justify-center space-x-2">
                <EyeIcon />
                <span>Photos</span>
              </div>
            }
          />
          <Tab id="/employees" href="/retailers/employees" title="Employees" />
          <Tab id="/followers" href="/retailers/followers" title="Followers" />
        </Tabs>**/}
      </div>
    );
  };

  return <div className="w-full h-screen">{quickLinks()}</div>;
}

export default Dashboard;
